 23	method ComputeFact (n:int) returns (f:int)
 24	requires n >=0
 25	ensures f== factorial(n)
 26	
 27	{   
 28	    assert 0 <= n <= n && 1*factorial(n) == factorial(n);
 29	    f:=1;
 30	    assert 0 <= n <= n && f*factorial(n) == factorial(n);
 31	    var x:=n;
 32	    assert 0 <= x <= n && f*factorial(x) == factorial(n);
 33	    while x > 0 
 34	        invariant 0 <= x <= n;
 35	        invariant f*factorial(x)== factorial(n);
 36	        decreases x-0;
 37	    {
