 74	    x:=1;
 75	    while y < a 
 76	        invariant 1 <= y <= a;
 77	        invariant y*y==x;
 78	    {
 79	        assert (y+1)*(y+1)==x+ (2*(y+1)-1) && 1 <= (y+1) <= a;
 80	        y:= y+1;
 81	        assert y*y==x+ (2*y-1) && 1 <= y <= a;
 82	        x:= x+ (2*y-1);
 83	        assert y*y==x && 1 <= y <= a;
 84	    }
 85	    assert y*y==x && 1 <= y <= a;
 86	}
