101	        Sqare_Lemma(n-1);
102	        assert sumSerie(n-1) ==(n-1)*(n-1);
103	
104	        calc == {
105	            sumSerie(n);
106	            sumSerie(n-1) + 2*n -1;
107	            {
108	                Sqare_Lemma(n-1);
